function commercialTemplate(templates, name, language, variables) {
  const template = (templates || []).find(
    item =>
      item.name === name &&
      item.language?.toLowerCase() === language?.toLowerCase() &&
      item.status?.toLowerCase() === 'approved'
  );
  const body = template?.components?.find(item => item.type === 'BODY')?.text;
  const names = [
    ...new Set(
      [...(body || '').matchAll(/\{\{\s*([^{}]+?)\s*\}\}/g)].map(
        match => match[1]
      )
    ),
  ];
  const unsupported = template?.components?.some(
    item =>
      (item.type === 'HEADER' && item.format !== 'TEXT') ||
      (item.type !== 'BODY' && JSON.stringify(item).includes('{{'))
  );
  if (
    !body ||
    unsupported ||
    (names.length && template.parameter_format !== 'NAMED') ||
    names.some(key => !variables[key]?.trim())
  ) {
    throw new Error(
      'Plantilla Meta no disponible o parametros incompletos: ' + name
    );
  }
  return {
    name: template.name,
    category: template.category,
    language: template.language,
    processed_params: {
      body: Object.fromEntries(names.map(key => [key, variables[key]])),
    },
    content: body.replace(
      /\{\{\s*([^{}]+?)\s*\}\}/g,
      (match, key) => variables[key]
    ),
  };
}

function classifyCommercial(
  conversations,
  pages,
  cfg,
  templateConfig,
  now,
  renderTemplate
) {
  const contexts = new Map(
    pages
      .flatMap(page => page.contexts)
      .map(c => [String(c.conversation_id), c])
  );
  const seen = new Set();
  const output = [];
  const today = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'America/Argentina/Buenos_Aires',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(new Date(now));
  const norm = value =>
    String(value || '')
      .toLowerCase()
      .trim();
  const aliases = value =>
    String(value || '')
      .split(',')
      .map(norm);
  const day = value =>
    new Intl.DateTimeFormat('en-CA', {
      timeZone: 'America/Argentina/Buenos_Aires',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
    }).format(new Date(value));
  conversations.forEach(c => {
    if (seen.has(String(c.id))) return;
    seen.add(String(c.id));
    const ctx = contexts.get(String(c.id));
    if (!ctx?.commercial_allowed || !ctx.opportunity_reference) return;
    const labels = (c.labels || []).map(norm);
    if (!labels.includes(norm(cfg.label_seguimiento))) return;
    // A client message still awaiting a human reply never becomes customer silence.
    if (
      !ctx.last_human_at ||
      !ctx.last_client_at ||
      Date.parse(ctx.last_client_at) >= Date.parse(ctx.last_human_at)
    )
      return;
    const sent = Number(ctx.follow_up?.sent_count || 0);
    const last = ctx.follow_up?.last_sent_at;
    if (ctx.state === 'inactive') {
      output.push({
        json: {
          conversation_id: c.id,
          opportunity_reference: ctx.opportunity_reference,
          accion: 'terminar',
          marcar_inactivo: true,
          labels_finales: [
            ...labels.filter(
              l =>
                l !== norm(cfg.label_seguimiento) &&
                l !== norm(cfg.label_inactivo)
            ),
            norm(cfg.label_inactivo),
          ],
        },
      });
      return;
    }
    if (ctx.state !== 'in_progress' || sent >= 3) return;
    if (
      sent > 0 &&
      (!last || (Date.parse(today) - Date.parse(day(last))) / 86400000 < 2)
    )
      return;
    const assigned = norm(
      c.meta?.assignee?.available_name || c.meta?.assignee?.name
    );
    let seller = '';
    if (aliases(cfg.alias_juli).some(a => a && assigned.includes(a)))
      seller = 'juli';
    else if (aliases(cfg.alias_marcos).some(a => a && assigned.includes(a)))
      seller = 'marcos';
    if (!seller) return;
    const advisor = seller.charAt(0).toUpperCase() + seller.slice(1);
    let product = cfg.producto_generico;
    if (labels.includes(norm(cfg.label_bici))) product = cfg.producto_bici;
    else if (labels.includes(norm(cfg.label_aparatos)))
      product = cfg.producto_aparatos;
    const step = sent + 1;
    const template = renderTemplate(
      templateConfig.commercial_templates?.[String(c.inbox_id)],
      ['seg_dia_1', 'seg_dia_3', 'seg_dia_5'][step - 1],
      cfg.template_language,
      { asesor: advisor, producto: product }
    );
    output.push({
      json: {
        conversation_id: c.id,
        opportunity_reference: ctx.opportunity_reference,
        accion: 'enviar',
        paso: step,
        envio_numero: step,
        fecha_envio: today,
        ultimo_envio_previo: last ? day(last) : '',
        vendedor: seller,
        asesor: advisor,
        producto: product,
        template_name: template.name,
        template_category: template.category,
        template_language: template.language,
        processed_params: template.processed_params,
        template_content: template.content,
      },
    });
  });
  return output;
}
const contextPages = $('Contextos Comerciales').all().map(item => item.json);
if (contextPages[0].config.funnel_enabled === true) {
  const cfg = $('Config Chatwoot').first().json;
  const now = $now.setZone('America/Argentina/Buenos_Aires');
  if (String(cfg.dias_sin_envio || '').split(',').map(Number).includes(now.weekday)) return [];
  return classifyCommercial($input.all().flatMap(item => item.json.payload ?? item.json.data?.payload ?? []), contextPages, cfg, $('Compras para Coordinacion Comercial').first().json.config, now.toISO(), commercialTemplate);
}
